#pragma once
#include <QString>
#include <QStringList>
#include <QRegularExpression>
#include "bank.hpp"
namespace scriptedchat {
struct PriceInput{bool found=false,valid=false,discount=false; perekup::Money value=0;};
inline QString normalized(QString value){return value.toLower().replace(QChar(0x451),QChar(0x435));}
inline PriceInput priceInput(QString text){
 // Currency is explicit: Cyrillic р (and its full spelling), not Latin p.
 static const QRegularExpression expression(QStringLiteral("(?<![\\p{L}\\p{N}])([0-9]{1,3}(?:[ \\x{00a0}\\x{202f}][0-9]{3})+|[0-9]+)(?:[.,]([0-9]{1,3}))?\\s*(тыс(?:яч(?:а|и|у)?)?\\.?|к|млн\\.?|миллион(?:а|ов)?)?\\s*(р(?:уб(?:лей|ля|ль|ли)?)?\\.?|₽)(?![\\p{L}\\p{N}])"),QRegularExpression::CaseInsensitiveOption|QRegularExpression::UseUnicodePropertiesOption);
 PriceInput result;auto matches=expression.globalMatch(text);if(!matches.hasNext())return result;auto match=matches.next();result.found=true;if(matches.hasNext())return result;auto lower=normalized(text);if(QRegularExpression(QStringLiteral("(?:[0-9]|[-−])\\s*$")).match(text.left(match.capturedStart())).hasMatch())return result;if(QRegularExpression(QStringLiteral("не\\s+(?:предлагаю|дам|плачу|беру|забираю|готов|согласен)")).match(lower).hasMatch())return result;
 auto whole=match.captured(1);whole.remove(QRegularExpression(QStringLiteral("[ \\x{00a0}\\x{202f}]")));bool ok=false;auto integer=whole.toLongLong(&ok);if(!ok||integer<=0)return result;auto unit=normalized(match.captured(3));qint64 multiplier=unit.startsWith(QStringLiteral("м"))?1000000:unit.isEmpty()?1:1000;if(integer>perekup::safeInteger/multiplier)return result;qint64 amount=integer*multiplier;auto fraction=match.captured(2);if(!fraction.isEmpty()){qint64 divisor=1;for(int n=0;n<fraction.size();++n)divisor*=10;if(multiplier==1||(fraction.toLongLong()*multiplier)%divisor)return result;amount+=fraction.toLongLong()*multiplier/divisor;}if(amount<1||amount>perekup::safeInteger)return result;
 result.valid=true;result.value=amount;result.discount=QRegularExpression(QStringLiteral("(?:скинь|скинете|скинуть|уступи|уступите|сбрось|убери|минус)\\b"),QRegularExpression::UseUnicodePropertiesOption).match(lower).hasMatch();return result;
}
inline bool readyToBuy(QString text){auto value=normalized(text).trimmed();if(value.contains('?')||QRegularExpression(QStringLiteral("(?:не\\s+(?:готов|беру|забира|соглас|договор|куп|буду)|не\\s+хочу|передумал|пока\\s+не|если|потом|когда)"),QRegularExpression::UseUnicodePropertiesOption).match(value).hasMatch())return false;return QRegularExpression(QStringLiteral("(?:\\bготов(?:а)?\\s+(?:забрать|купить|брать)\\b|\\bберу\\b|\\bзабираю\\b|\\bдоговорились\\b|\\bсоглас(?:ен|на)\\b)"),QRegularExpression::UseUnicodePropertiesOption).match(value).hasMatch();}
inline bool priceQuestion(const QString& input){auto value=normalized(input);return value.contains(QStringLiteral("цен"))||value.contains(QStringLiteral("торг"))||value.contains(QStringLiteral("уступ"))||value.contains(QStringLiteral("скид"))||value.contains(QStringLiteral("скинь"));}
inline QString visibleFacts(const perekup::Json& car){return QString::fromStdString(car.value("name",""))+"\n"+QString::fromStdString(car.value("desc",""))+"\n"+QString::fromStdString(car.value("full",""));}
inline QString reply(const QString& input,const perekup::Json& car){auto lower=normalized(input);if(lower.contains(QStringLiteral("привет"))||lower.contains(QStringLiteral("здрав")))return QStringLiteral("Здравствуйте! Да, объявление актуально. Что хотите узнать о машине?");if((lower.contains(QStringLiteral("дтп"))||lower.contains(QStringLiteral("битая")))&&!normalized(visibleFacts(car)).contains(QStringLiteral("дтп")))return QStringLiteral("В объявлении нет сведений о ДТП. Это нужно уточнить при осмотре.");if(QRegularExpression(QStringLiteral("как дела|как сам|как оно|ты тут")).match(lower).hasMatch())return QStringLiteral("На связи. Что хотите узнать о машине?");if(priceQuestion(input))return QStringLiteral("Напишите вашу цену с буквой р, например «250 000 р», и обсудим.");if(lower.contains(QStringLiteral("спасибо")))return QStringLiteral("Пожалуйста. Если остались вопросы по объявлению, спрашивайте.");if(QRegularExpression(QStringLiteral("пробег|короб|варик|мотор|двиг|трансм|топлив|дизел|бензин")).match(lower).hasMatch())return QString::fromStdString(car.value("desc",""));if(lower.contains(QStringLiteral("цвет"))){auto m=QRegularExpression(QStringLiteral("Цвет кузова[^.]*\\.?"),QRegularExpression::CaseInsensitiveOption).match(visibleFacts(car));if(m.hasMatch())return m.captured();}return QStringLiteral("Точнее получится ответить после осмотра. Что ещё хотите уточнить по объявлению?");}
}
